import axios from "axios"
import { useState } from "react"


function Auth() {
    const [email, setEmail] = useState()
    const [username, setUsername] = useState()
    const [password, setPassword] = useState()
    
    const url = "localhost:8000/api/auth/users/"
    const valuesChanged = ()=>{
        setUsername(document.getElementById('1'))
        setUsername(document.getElementById('2'))
        setUsername(document.getElementById('3'))
    }
    const Login = async()=>{
        try{
            const resp = axios.post(url, {
                username: username,
                email: email,
                password: password
            })
        }
        catch{

        }
        return resp
    }
    return ( 
        <>
        <form method="POST" action="/auth/users/">
        <p>Имя</p>
        <input type="text" id='1' name="username" onChange={valuesChanged}/>
        <p>Почта</p>
        <input type="text" id='2' name="email" onChange={valuesChanged}/>
        <p>Пароль</p>
        <input type="password" id='3' name="password" onChange={valuesChanged}/>
        <button action={login}></button>
        </form>
        </>
    );
}

export default Auth;
